import {CHAPTERS,ITEMS,SILLY,DECOR,itemById} from './adventure-data.js';
import {currentItem,markFound,answerCard,advanceItem,attachSticker,finishOwner,placeItem,attachLabel,stars,setDecor,canTravel,nextChapter} from './adventure-model.js';
import {drawArtifact} from './artwork.js';
import {drawCharacter} from './characters.js';
import {icon,sillyIcons} from './adventure-art.js';
import {ARTIFACT_STORIES} from './artifact-stories.js';
import {FRIEND_NAMES,ROUTES,canRoute} from './companion-model.js';
import {uiIcon} from './ui-icons.js';

export function createAdventureUI(root,s,{onDig,onSave,onHome,onSound,onReplay,onTrail}){
 let view='',selected='',tab='place',note='',name=0,spots=new Set(),comic=null,visitor=0;
 let described='',detailReturn='card',feature=-1;
 function describe(id,back='card',point=-1){described=id;detailReturn=back;feature=point;comic=null;const i=itemById(id),f=ARTIFACT_STORIES[id],lines=point<0?f.hello:f.spots[point].talk;render('describe',i.name,`<div class="artifact-passport"><span>${f.period}</span><span>${f.age}</span><span>나온 곳 · ${f.place}</span></div><div class="artifact-visit"><div class="artifact-touch">${art(id)}${f.spots.map((p,n)=>`<button type="button" class="artifact-dot" data-feature="${n}" style="left:${p.x}%;top:${p.y}%" aria-label="${p.label} 살펴보기">${n+1}</button>`).join('')}</div><div class="artifact-dialogue"><h3>${f.what}</h3><div class="story-bubble" role="status">${lines.map(t=>`<p>${t}</p>`).join('')}</div><div class="artifact-feature">${f.spots.map((p,n)=>`<button data-feature="${n}" aria-pressed="${feature===n}">${n+1}. ${p.label}</button>`).join('')}</div><p class="artifact-caption">${f.note}</p></div></div><div class="artifact-footer">${btn(back==='museum'?'전시실로 돌아가기':back==='replay'?'다시 만난 유물!':'이 유물로 기억 찾기','describe-next','class="adv-primary"')}</div><p class="artifact-source">직접 그린 교육용 도판 · 이야기 근거: <a href="${f.source}" target="_blank" rel="noopener">국립박물관·우리역사넷 자료</a></p>`,'반짝이는 번호를 눌러 유물 이야기를 들어 봐.');}
 function friends(){render('friends','우리들의 특별한 능력',`<div class="ability-collection">${Object.entries(ROUTES).map(([id,r])=>`<button type="button" class="ability-card ${canRoute(s,id)?'earned':'waiting'}" data-route="${id}" ${canRoute(s,id)?'':'disabled'}><span class="ability-state">${s.routes.includes(id)?'함께 찾은 길':canRoute(s,id)?'출발 준비 완료':'아직 만나지 못한 길'}</span><div class="ability-portrait">${actor(r.who)}</div><strong>${r.reward}</strong><p>${{entry:'착지점을 골라 폴짝!',sky:'날아가서 흔적 찾기',brace:'받치고, 돌 틈 살피기',ridge:'다음 언덕으로 훨훨!'}[id]}</p><span class="ability-go">${s.routes.includes(id)?'한 번 더 놀기':canRoute(s,id)?'능력으로 길 열기':'앞선 기억을 찾으면 열려'}</span></button>`).join('')}</div><p class="story-bubble">뱀: 두꺼비는 폴짝, 새는 훨훨, 거북은 든든! 친구마다 여는 길이 달라.</p>`,'친구를 골라 새로운 길을 열어 봐.');}
 const art=(id,cls='')=>`<canvas class="adv-art ${cls}" data-art="${id}" role="img" aria-label="${itemById(id).name} 도판"></canvas>`;
 const actor=(who,cls='')=>`<canvas class="adv-actor ${cls}" data-actor="${who}" role="img" aria-label="${{frog:'두꺼비',snake:'뱀',turtle:'거북',bird:'새'}[who]} 토우"></canvas>`;
 const btn=(text,action,attrs='')=>`<button type="button" data-action="${action}" ${attrs}>${uiIcon(action)}<span>${text}</span></button>`;
 function paint(t=0){for(const c of root.querySelectorAll('canvas')){const r=c.getBoundingClientRect(),dp=Math.min(devicePixelRatio||1,2);if(!r.width||!r.height)continue;const w=Math.round(r.width*dp),h=Math.round(r.height*dp);if(c.width!==w||c.height!==h){c.width=w;c.height=h;}if(c.dataset.art){c.getContext('2d').clearRect(0,0,w,h);drawArtifact(c.getContext('2d'),c.dataset.art,0,0,w,h);}else drawActor(c,t);}}
 function drawActor(c,t){const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);drawCharacter(ctx,c.dataset.actor,w/2,h*.93,Math.min(w,h)*.95,t,comic?'collapse':'idle',!!comic,matchMedia('(prefers-reduced-motion: reduce)').matches);}
 new ResizeObserver(()=>paint()).observe(root);
 function replayTray(){const unlocked=ITEMS.filter(i=>i.kind==='dig'&&s.completed.some(n=>CHAPTERS[n].items.includes(i.id)));if(!unlocked.length)return;const tray=document.createElement('div');tray.className='replay-tray';tray.innerHTML=`<h3>한 번 더 파고 싶어?</h3><p>전시는 그대로 두고, 좋아하는 유물을 다시 찾아봐!</p><div>${unlocked.map(i=>`<button type="button" data-replay="${i.id}">${art(i.id)}<span>${i.name}</span></button>`).join('')}</div>`;root.append(tray);paint();}
 function replayAward(id){comic=null;render('replay','또 찾았다!',`<div class="sticker-award">${art(id)}<strong>${itemById(id).name}</strong></div><p class="story-bubble">두꺼비: 또 파도 손끝이 간질간질해!</p><div class="adv-actions"><button type="button" class="adv-primary" data-replay="${id}">한 번 더!</button>${btn('박물관으로','museum')}</div>`);}
 function render(next,title,body,sub='',focus='#adv-title'){
  const same=view===next,scroll=root.scrollTop,active=root.contains(document.activeElement)?document.activeElement:null;
  const focusData=active?.tagName==='BUTTON'?Object.entries(active.dataset):[];
  view=next;root.classList.remove('hidden');root.classList.add('adventure');root.dataset.view=next;
  root.innerHTML=`<header class="adv-top"><div><small>${s.chapter+1}장 · ${CHAPTERS[s.chapter].title}</small><h2 id="adv-title" tabindex="-1">${title}</h2></div><nav aria-label="탐험 메뉴">${btn('첫 화면','home')}${btn('탐험 지도','map',`aria-pressed="${next==='map'}"`)}${btn('토우 능력','friends',`aria-pressed="${next==='friends'}"`)}${btn('내 박물관','museum',`aria-pressed="${next==='museum'}"`)}</nav></header>${sub?`<p class="adv-instruction">${sub}</p>`:''}${body}`;
  if(next==='describe')root.querySelector('.adv-top small').textContent='나의 유물 관찰 기록';
  root.scrollTop=same?scroll:0;paint();const restored=same&&focusData.length?[...root.querySelectorAll('button')].find(b=>focusData.every(([k,v])=>b.dataset[k]===v)&&!b.disabled):null;(restored||root.querySelector(focus))?.focus({preventScroll:true});
 }
 function map(){comic=null;render('map','다음 기억을 찾아서',`<div class="adventure-map">${CHAPTERS.map((ch,n)=>`<button type="button" class="map-island ${n===1&&!canTravel(s)&&s.chapter===0?'locked':''}" data-map="${n}" ${n===1&&!canTravel(s)&&s.chapter===0?'disabled':''}><img class="map-scene" src="assets/tomb-map-${n+1}.svg" alt="${ch.site}"><span class="chapter-number">${n+1}</span><h3>${ch.title}</h3><p>${ch.site}</p><strong>${s.completed.includes(n)?'전시한 기억 보러 가기':n===s.chapter?'탐험 이어가기':canTravel(s)?'새로운 기억이 기다려!':'첫 전시의 설명 스티커 3개를 붙이면 열려'}</strong></button>`).join('')}</div><div class="friend-parade">${['frog','snake','turtle','bird'].map(w=>`<div class="${s.friends.includes(w)?'':'unmet'}">${actor(w)}<span>${s.friends.includes(w)?{frog:'두꺼비',snake:'뱀',turtle:'거북',bird:'새'}[w]:'아직 못 만난 친구'}</span></div>`).join('')}</div>`,'언덕을 눌러 탐험을 이어 가자.');replayTray();}
 function intro(){comic=null;render('intro',CHAPTERS[s.chapter].title,`<div class="intro-stage">${actor(s.chapter?'bird':'snake')}${s.chapter?art('mounds'):icon('one-hill')}${actor(s.chapter?'snake':'frog',s.chapter?'':'unmet')}</div><div class="story-bubble">${CHAPTERS[s.chapter].intro.map(t=>`<p>${t}</p>`).join('')}</div>${btn(s.chapter?'새와 함께 출발!':'같이 파러 가자!','dig','class="adv-primary"')}`);}
 function survey(){render('survey','새의 눈으로 둘러봐!',`<div class="survey-ground">${art('mounds')}${actor('bird','flying-bird')}${[0,1].map(n=>`<button type="button" class="survey-spot spot-${n} ${spots.has(n)?'spotted':''}" data-spot="${n}" aria-label="${n?'북쪽':'남쪽'} 봉분 살펴보기">${spots.has(n)?'✓':'반짝'}</button>`).join('')}</div><p class="story-bubble">${spots.size===2?'새: 남쪽과 북쪽, 두 봉분이 이어졌어!':'새: 반짝이는 두 곳을 눌러 봐!'}</p>${btn('기억 조각 보기','survey-card',`class="adv-primary" ${spots.size===2?'':'disabled'}`)}`);}
 function card(){const i=currentItem(s);comic=null;render('card',i.question,`<div class="clue-play"><div class="artifact-hero">${art(i.id)}<span>${i.name}</span>${i.id==='saddle'?'<small>원본은 보존 · 복제 도판으로 관찰</small>':''}</div><div class="picture-choices">${i.choices.map((text,n)=>`<button type="button" data-answer="${n}" class="picture-choice ${s.misses[i.id]>=2&&n===i.answer?'friend-hint':''}">${icon(i.icons[n])}<strong>${text}</strong>${s.misses[i.id]>=2&&n===i.answer?'<small>두꺼비가 가리키는 쪽!</small>':''}</button>`).join('')}</div></div><p class="story-bubble">${i.hint}</p>`, '그림 두 개 중 하나를 눌러 봐.');}
 function showComic(){const i=currentItem(s);comic=i.comic;render('comic','앗, 잠깐!',`<div class="comic-stage comic-${i.comic}">${actor('frog')}${icon(i.icons[1-i.answer])}${actor(s.chapter?'bird':'snake')}</div><p class="story-bubble">${i.joke}</p><div class="adv-actions">${btn('다시 고르기','retry','class="adv-primary"')}${btn('한 번 더 보기','comic-again')}</div>`);}
 function award(){const i=currentItem(s);comic=null;render('award','기억 스티커를 찾았어!',`<div class="sticker-award">${art(i.id)}<strong>${i.clue}</strong></div><p class="story-bubble">${i.reason}</p><div class="memory-pockets">${CHAPTERS[s.chapter].items.map(id=>`<div class="${s.clues.includes(id)?'filled':''}">${s.clues.includes(id)?art(id):'?'}<span>${s.clues.includes(id)?itemById(id).clue:'아직 흐릿한 기억'}</span></div>`).join('')}</div>${btn(i.next,'next','class="adv-primary"')}`);}
 function portrait(){const ids=CHAPTERS[s.chapter].items,owned=s.owners[s.chapter];render('portrait','주인에게 기억을 붙여 줘!',`<div class="owner-workshop"><div class="real-stickers">${ids.map(id=>`<button type="button" data-sticker="${id}" aria-pressed="${owned.includes(id)}">${art(id)}<span>${owned.includes(id)?'✓ ':''}${itemById(id).clue}</span></button>`).join('')}</div><div class="owner-portrait ${comic?'goofy':''}"><div class="owner-person">${icon('person')}${s.chapter?'<div class="second-person">'+icon('person')+'</div>':''}</div>${ids.map((id,n)=>`<div class="portrait-sticker sticker-${n} ${owned.includes(id)?'attached':''}">${owned.includes(id)?art(id):'＋'}</div>`).join('')}${comic?`<div class="silly-flight">${icon(sillyIcons[Number(comic)-1])}</div>`:''}<small>유물로 꾸민 상상 모습 · 실제 얼굴은 몰라</small></div><div class="silly-stickers">${SILLY.map((label,n)=>`<button type="button" data-silly="${n}">${icon(sillyIcons[n])}<span>${label}</span></button>`).join('')}</div></div><p class="story-bubble" role="status">${note||'기억 스티커를 눌러 붙여 봐. 엉뚱한 것도 눌러 볼래?'}</p><div class="nickname-row">${CHAPTERS[s.chapter].names.map((n,k)=>`<button type="button" data-name="${k}" aria-pressed="${name===k}">${n}</button>`).join('')}</div>${btn('이 별명으로 전시 열기','finish-owner',`class="adv-primary" ${owned.length===3?'':'disabled'}`)}`);}
 function museum(){comic=null;const count=stars(s),picked=itemById(selected),inSlots=s.slots.includes(selected);const visitorLines=['두꺼비: 내가 고른 자리, 어때?','거북: 설명 스티커까지 붙였네. 기억하기 좋다!','새: 다음 언덕도 보러 가자!','뱀: 내 자리도 꾸며 줘. 아주 넓게.'];render('museum','우리의 박물관',`<div class="museum-toolbar"><strong class="star-counter">★ ${count}</strong><span>${note||'유물을 고르고 빈 전시대를 눌러 줘.'}</span><div>${btn('전시하기','tab-place',`aria-pressed="${tab==='place'}"`)}${btn('꾸미기','tab-decor',`aria-pressed="${tab==='decor'}"`)}</div></div><div class="museum-play"><div class="museum-room" style="--wall:${DECOR.wall[s.decor.wall].color};--floor:${DECOR.floor[s.decor.floor].color};--light:${DECOR.light[s.decor.light].color}"><div class="museum-sign">${s.names.filter(Boolean).join(' · ')||'기억을 기다리는 전시실'}</div><div class="plinths">${s.slots.map((id,n)=>`<button type="button" class="plinth ${id===selected?'selected':''}" data-slot="${n}" aria-label="${n+1}번 전시대 ${id?itemById(id).name:'비어 있음'}">${id?art(id):'<b>＋</b>'}<span>${id?itemById(id).name:'놓아 줘'}</span>${id?`<small>${s.labels.includes(id)?'★★★':'★'} ${s.labels.includes(id)?itemById(id).clue:''}</small>`:''}</button>`).join('')}</div></div><aside class="museum-kit">${tab==='place'?`<h3>내가 찾은 기억</h3><div class="collected-tray">${s.clues.map(id=>`<button type="button" data-pick="${id}" aria-pressed="${selected===id}">${art(id)}<span>${itemById(id).name}</span></button>`).join('')||'<p>먼저 언덕에서 유물을 찾아보자!</p>'}</div>${picked?`<p>${picked.name}</p><p class="artifact-caption">${ARTIFACT_STORIES[picked.id].period}<br>${ARTIFACT_STORIES[picked.id].place}</p>${btn('\uC720\uBB3C \uC774\uC57C\uAE30 \uB2E4\uC2DC \uBCF4\uAE30','info')}${btn(s.labels.includes(selected)?'설명 스티커 붙였어!':'설명 스티커 붙이기 +★★','label',`${!inSlots||s.labels.includes(selected)?'disabled':''} class="adv-primary"`)}`:''}`:`<h3>별로 열린 꾸미기</h3>${Object.entries(DECOR).map(([kind,list])=>`<fieldset><legend>${{wall:'벽지',floor:'바닥',light:'조명'}[kind]}</legend>${list.map((d,n)=>`<button type="button" data-decor="${kind}" data-level="${n}" aria-pressed="${s.decor[kind]===n}" ${count<d.need?'disabled':''}><i style="background:${d.color}"></i>${d.name}${count<d.need?` ★${d.need}`:''}</button>`).join('')}</fieldset>`).join('')}`}</aside></div><footer class="museum-footer"><button type="button" class="visitor" data-action="visitor" aria-label="토우 손님 반응 보기">${actor(['frog','turtle','bird','snake'][visitor%4])}</button><p>${visitorLines[visitor%4]}</p>${canTravel(s)?btn('새와 두 번째 무덤으로!','travel','class="adv-primary"'):s.chapter===1&&s.completed.includes(1)&&s.labels.length===6?btn('두 이야기의 마지막 인사','ending','class="adv-primary"'):btn('탐험 지도','map')}</footer>`);}
 function ending(){render('ending','우리가 이어 준 두 이야기',`<div class="ending-friends">${s.friends.map(w=>actor(w)).join('')}</div><p class="story-bubble">${CHAPTERS[1].ending}</p><div class="ending-collections">${s.clues.map(id=>art(id)).join('')}</div><p>진짜 이름과 두 무덤 주인의 관계는 아직 몰라.</p><div class="adv-actions">${btn('박물관 더 꾸미기','museum','class="adv-primary"')}${btn('탐험 지도 보기','map')}</div>`);}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action;
  if(b.dataset.feature!==undefined&&view==='describe'){describe(described,detailReturn,Number(b.dataset.feature));onSound('solved');return;}
  if(b.dataset.route){onTrail(b.dataset.route);return;}
  if(b.dataset.replay){onReplay(b.dataset.replay);return;}
  if(b.dataset.map!==undefined){const n=Number(b.dataset.map);if(n===1&&s.chapter===0){if(!nextChapter(s))return;onSave();}if(s.completed.includes(n))museum();else intro();return;}
  if(b.dataset.answer!==undefined&&view==='card'){const result=answerCard(s,currentItem(s).id,Number(b.dataset.answer));onSave();onSound(result);result==='retry'?showComic():result==='solved'?award():null;return;}
  if(b.dataset.sticker&&view==='portrait'){attachSticker(s,b.dataset.sticker);note='착! '+itemById(b.dataset.sticker).clue+'의 기억을 붙였어.';comic=null;onSound('solved');onSave();portrait();return;}
  if(b.dataset.silly!==undefined&&view==='portrait'){comic=String(Number(b.dataset.silly)+1);note=`두꺼비: ${SILLY[Number(b.dataset.silly)]}? 이건 옛 주인의 단서가 아니네!`;onSound('retry');portrait();return;}
  if(b.dataset.name!==undefined){name=Number(b.dataset.name);comic=null;portrait();return;}
  if(b.dataset.spot!==undefined&&view==='survey'){spots.add(Number(b.dataset.spot));onSound('solved');survey();return;}
  if(b.dataset.pick){selected=b.dataset.pick;note='빈 전시대에 놓거나, 이미 놓은 유물의 설명을 붙여 줘.';museum();return;}
  if(b.dataset.slot!==undefined&&view==='museum'){const n=Number(b.dataset.slot);if(!selected&&s.slots[n])selected=s.slots[n];else if(selected){const placed=placeItem(s,selected,n);note=placed?'톡! 전시했어. 설명 스티커도 붙여 줘.':'새 유물은 빈 전시대에 놓아 줘.';onSave();}museum();return;}
  if(b.dataset.decor){setDecor(s,b.dataset.decor,Number(b.dataset.level));note='우리 박물관 분위기가 달라졌어!';onSave();museum();return;}
  switch(action){case'friends':friends();break;case'info':if(selected)describe(selected,'museum');break;case'describe-next':detailReturn==='museum'?museum():detailReturn==='replay'?replayAward(described):card();break;case'map':map();break;case'home':onHome();break;case'museum':note='';museum();break;case'dig':root.classList.add('hidden');onDig();break;case'retry':card();break;case'comic-again':showComic();break;case'next':if(advanceItem(s)){onSave();if(s.index===3){note='진짜 이름은 몰라도, 우리만의 별명은 붙일 수 있어.';name=0;portrait();}else onDig();}break;case'survey-card':if(spots.size===2){markFound(s);onSave();describe(currentItem(s).id);}break;case'finish-owner':if(finishOwner(s,name)){onSave();selected='';note='유물을 놓고 설명 스티커를 붙여 별을 모아 봐!';museum();}break;case'label':if(attachLabel(s,selected)){onSave();note='설명을 붙여 별 3개! 꾸미기가 열렸는지 봐!';onSound('solved');museum();}break;case'tab-place':tab='place';museum();break;case'tab-decor':tab='decor';museum();break;case'visitor':visitor++;museum();break;case'travel':if(nextChapter(s)){onSave();intro();}break;case'ending':if(s.completed.includes(1)&&s.labels.length===6)ending();break;}
 });
 return {map,intro,card,award,museum,portrait,replayAward,describe,friends,survey(){spots=new Set();survey();},reset(){selected='';tab='place';note='';name=0;spots=new Set();comic=null;visitor=0;described='';detailReturn='card';feature=-1;root.classList.add('hidden');root.innerHTML='';view='';},hide(){root.classList.add('hidden');root.innerHTML='';view='';},tick(t){for(const c of root.querySelectorAll('[data-actor]'))drawActor(c,t);}};
}
